"use client"

import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { useI18n } from "@/lib/i18n"
import { todayStr, monthStartStr, addDaysStr } from "@/lib/acct-client"

export function DateRange({ from, to, onChange }: { from: string; to: string; onChange: (from: string, to: string) => void }) {
  const { t } = useI18n()
  const now = new Date()
  const presets = [
    { k: "acct.range.thisMonth", f: monthStartStr(now), t: todayStr(now) },
    { k: "acct.range.lastMonth", f: monthStartStr(new Date(now.getFullYear(), now.getMonth() - 1, 1)), t: todayStr(new Date(now.getFullYear(), now.getMonth(), 0)) },
    { k: "acct.range.last30", f: addDaysStr(todayStr(now), -29), t: todayStr(now) },
    { k: "acct.range.thisYear", f: `${now.getFullYear()}-01-01`, t: todayStr(now) },
  ]
  return (
    <div className="flex flex-wrap items-end gap-2">
      <div className="grid gap-1">
        <span className="text-xs text-muted-foreground">{t("acct.from")}</span>
        <Input type="date" value={from} max={to} onChange={(e) => onChange(e.target.value, to)} className="h-9 w-[150px]" aria-label={t("acct.from")} />
      </div>
      <div className="grid gap-1">
        <span className="text-xs text-muted-foreground">{t("acct.to")}</span>
        <Input type="date" value={to} min={from} onChange={(e) => onChange(from, e.target.value)} className="h-9 w-[150px]" aria-label={t("acct.to")} />
      </div>
      <div className="flex flex-wrap gap-1">
        {presets.map((p) => (
          <Button key={p.k} type="button" size="sm" variant={from === p.f && to === p.t ? "default" : "outline"} className="h-9" onClick={() => onChange(p.f, p.t)}>
            {t(p.k)}
          </Button>
        ))}
      </div>
    </div>
  )
}
